  // ---------- remedies (plain) ----------
  function remedies(ctx, vd, m) {
    const X = make(ctx, vd, m);
    const seq = (ctx.dasha && ctx.dasha.fullSeq) || [];
    const now = Date.now();
    const md = seq.find((x) => ms(x.start) <= now && ms(x.end) >= now);
    const ad = md && (md.antardashas || []).find((a) => ms(a.start) <= now && ms(a.end) >= now);
    const weak = P7.filter((k) => ["deb", "en"].includes(X.dig(k)) || (X.c[k] && X.c[k].combust)).sort((a, b) => X.strength(a) - X.strength(b));
    const list = [...new Set([LORD[X.asc], md && md.lord, ad && ad.lord].concat(weak.slice(0, 2)).filter(Boolean))].slice(0, 5);
    const why = (k) => k === LORD[X.asc] ? "लग्नेश — आपकी सेहत और आत्मबल का ग्रह" : (md && k === md.lord ? "वर्तमान महादशा का स्वामी" : (ad && k === ad.lord ? "वर्तमान अंतर्दशा का स्वामी" : "कमज़ोर स्थिति वाला ग्रह"));
    return list.map((k) => { const r = REMEDY[k]; return `<div class="bx keep"><h4>${PL[k]} <span class="muted">(${why(k)})</span></h4><p><b>मंत्र:</b> "${r.m}" — ${r.d} से शुरू करके रोज़ 108 बार।<br><b>दान:</b> ${r.d} को ${r.dan}।<br><b>सरल उपाय:</b> ${r.s}</p></div>`; }).join("");
  }


