  // ---------- wealth — full ----------
  const SOURCE = { Sun: "सरकार, अधिकार वाले पद, पिता या बड़े संस्थान", Moon: "जनता से जुड़े काम, खाद्य-पेय, यात्रा या महिलाओं से जुड़े व्यवसाय", Mars: "ज़मीन-जायदाद, तकनीकी काम, मशीनरी, पुलिस-सेना या खेल", Mercury: "व्यापार, लेखा-जोखा, संचार, परामर्श, लेखन या कमीशन", Jupiter: "अध्यापन, सलाह, बैंक-वित्त, क़ानून या धार्मिक-सामाजिक काम", Venus: "कला, फ़ैशन, सौंदर्य, मनोरंजन, वाहन या विलासिता की वस्तुएँ", Saturn: "लंबी मेहनत, उद्योग, निर्माण, तेल-लोहा, कर्मचारियों से काम या नौकरी", Rahu: "विदेश, तकनीक, आयात-निर्यात, ऑनलाइन या असामान्य माध्यम", Ketu: "शोध, विशेष तकनीकी कौशल, आध्यात्मिक या सलाह से जुड़े काम" };
